CREATE TABLE IF NOT EXISTS plexus_state.road_jobs (`id` String,`region_id` String,`region` String,`scenario` String,`changes` Array(Tuple(`way_id` Int64,`speed_factor` Float64)),`status` String,`completed` Int64,`total` Int64,`version` String,`result` Array(Tuple(`before` Float64,`after` Float64,`delta` Float64,`relative_percent` Nullable(Float64),`population` Int64,`settlements` Int64,`changed_edges` Int64,`normalization` Float64,`elapsed_seconds` Float64,`affected_settlements` Nullable(Int64),`money` Array(Tuple(`before_hours` Float64,`after_hours` Float64,`hours_saved_per_trip` Float64,`annual_hours_saved` Float64,`annual_gross_rub` Float64,`annual_net_rub` Float64,`simple_payback_years` Nullable(Float64),`assumptions` Tuple(`origin_point_id` String,`market_city` String,`trips_per_year` Float64,`rub_per_hour` Float64,`capital_cost_rub` Float64,`annual_operating_cost_rub` Float64),`method` String)),`routing_method` String,`settlement_effects` Array(Tuple(`point_id` String,`before` Float64,`after` Float64,`delta` Float64)))),`error` Nullable(String),`addition` Array(Tuple(`source_node` Int64,`target_node` Int64,`travel_hours` Float64,`coordinates` Array(Array(Array(Float64))))),`money_assumptions` Array(Tuple(`origin_point_id` String,`market_city` String,`trips_per_year` Float64,`rub_per_hour` Float64,`capital_cost_rub` Float64,`annual_operating_cost_rub` Float64)),updated UInt64) ENGINE=ReplacingMergeTree(updated) ORDER BY (id) SETTINGS index_granularity=256;

CREATE TABLE IF NOT EXISTS plexus_state.analysis_jobs (`id` String,`job` Tuple(`id` String,`region_id` String,`region` String,`mode` String,`percent` Int64,`fingerprint` String,`status` String,`stage` String,`candidates` Array(Tuple(`way_id` Int64,`name` String,`length_km` Float64,`score` Float64,`isolation_score` Float64,`crosses_boundary` Bool)),`results` Array(Tuple(`candidate` Tuple(`way_id` Int64,`name` String,`length_km` Float64,`score` Float64,`isolation_score` Float64,`crosses_boundary` Bool),`before` Float64,`after` Float64,`delta` Float64,`affected_population` Int64,`isolated_population` Int64,`elapsed_seconds` Float64)),`failures` Array(Tuple(`way_id` Int64,`code` String)),`candidate_count` Int64,`batch_target` Int64,`current_way_id` Nullable(Int64),`completed` Int64,`total` Int64,`elapsed_seconds` Float64,`error` Nullable(String),`compatible` Bool),`boundary` Tuple(`id` String,`name` String,`bounds` Tuple(Float64,Float64,Float64,Float64),`polygons` Array(Array(Array(Tuple(Float64,Float64))))),updated UInt64) ENGINE=ReplacingMergeTree(updated) ORDER BY (id) SETTINGS index_granularity=256;

CREATE TABLE IF NOT EXISTS plexus_state.analysis_details (`analysis_id` String,`way_id` Int64,`detail` Tuple(`result` Tuple(`candidate` Tuple(`way_id` Int64,`name` String,`length_km` Float64,`score` Float64,`isolation_score` Float64,`crosses_boundary` Bool),`before` Float64,`after` Float64,`delta` Float64,`affected_population` Int64,`isolated_population` Int64,`elapsed_seconds` Float64),`lines` Array(Array(Array(Float64))),`settlements` Array(Tuple(`impact` Tuple(`point_id` String,`population` Int64,`before` Float64,`after` Float64,`delta` Float64,`newly_isolated` Bool,`affected` Bool),`name` String,`longitude` Float64,`latitude` Float64))),updated UInt64) ENGINE=ReplacingMergeTree(updated) ORDER BY (analysis_id,way_id) SETTINGS index_granularity=256;
